import{c as o,Q as i,j as t,m as a}from"./chunks/framework.g_l1frA7.js";const u=JSON.parse('{"title":"Contributing","description":"","frontmatter":{},"headers":[],"relativePath":"developers/contributing.md","filePath":"developers/contributing.md","lastUpdated":null}'),c={name:"developers/contributing.md"};function s(d,e,r,n,l,p){return i(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="contributing" tabindex="-1">Contributing <a class="header-anchor" href="#contributing" aria-label="Permalink to &quot;Contributing&quot;">​</a></h1><h2 id="ground-rules" tabindex="-1">Ground rules <a class="header-anchor" href="#ground-rules" aria-label="Permalink to &quot;Ground rules&quot;">​</a></h2><ul><li><strong>Design tokens first</strong> — see <a href="/FinSight/developers/css">CSS &amp; Design</a>.</li><li><strong>Typed API</strong> — do not add raw fetches; extend the typed RPC surface and regenerate the contract.</li><li><strong>Tests</strong> — Rust + frontend tests must stay green. See <a href="/FinSight/developers/testing">Testing</a>.</li><li><strong>No second source of truth</strong> — routes, command lists, and schemas each have one canonical file and a parity test.</li></ul><h2 id="adding-a-command" tabindex="-1">Adding a command <a class="header-anchor" href="#adding-a-command" aria-label="Permalink to &quot;Adding a command&quot;">​</a></h2><ol><li>Body as <code>pub async fn my_cmd(state: &amp;ApiState, ...)</code> in <code>crates/finsight-api/src/commands/</code>.</li><li><code>#[utoipa::path]</code> + <code>ToSchema</code> on handler/DTOs; add to <code>finsight-openapi::COMMANDS</code> (sorted, identical to <code>dispatch.rs::SUPPORTED</code>).</li><li>Dispatcher arm in <code>crates/finsight-server/src/dispatch.rs</code> via <code>rpc_routes!(…)</code> using <code>arg(&amp;p, &quot;camelCase&quot;)</code>.</li><li><code>pnpm openapi</code> + <code>cargo test -p finsight-server --test parity</code> + <code>cargo test -p finsight-openapi</code>.</li><li><code>pnpm typecheck</code> — fix hooks for any DTO shape change.</li></ol><h2 id="adding-a-screen" tabindex="-1">Adding a screen <a class="header-anchor" href="#adding-a-screen" aria-label="Permalink to &quot;Adding a screen&quot;">​</a></h2><ol><li>File in <code>ui/src/screens/</code>, route in <code>ui/src/App.tsx</code>.</li><li>Path in <code>ui/src/routes.ts::APP_ROUTES</code> and <code>crates/finsight-core/src/routes.rs::APP_ROUTES</code> (mirrored).</li><li><code>routes.test.ts</code> enforces all three copies match — the test tells you which you forgot.</li></ol><h2 id="migrations" tabindex="-1">Migrations <a class="header-anchor" href="#migrations" aria-label="Permalink to &quot;Migrations&quot;">​</a></h2><p>Add SQL files to <code>crates/finsight-core/migrations/</code> named <code>V00N__description.sql</code>. Discovered automatically by Refinery via <code>embed_migrations!</code>. Current latest is <code>V016</code>, next is <code>V017__description.sql</code>.</p><h2 id="docs" tabindex="-1">Docs <a class="header-anchor" href="#docs" aria-label="Permalink to &quot;Docs&quot;">​</a></h2><p>Docs live in <code>docs/</code> (VitePress). Adding a page is a Markdown file plus one navigation entry in <code>docs/.vitepress/config.ts</code> — no component required. See <code>&quot;docs:dev&quot;</code> / <code>&quot;docs:build&quot;</code> scripts.</p><h2 id="pr-checklist" tabindex="-1">PR checklist <a class="header-anchor" href="#pr-checklist" aria-label="Permalink to &quot;PR checklist&quot;">​</a></h2><ul><li>[ ] <code>cargo fmt</code> + <code>cargo clippy -- -D warnings</code></li><li>[ ] <code>cargo test --workspace</code></li><li>[ ] <code>pnpm --filter ui typecheck</code> + <code>pnpm --filter ui test</code></li><li>[ ] <code>pnpm openapi</code> regenerated if you touched the API</li><li>[ ] <code>pnpm docs:build</code> passes (no broken links)</li></ul><p>See also: <a href="/FinSight/developers/css">Design Conventions</a>, <a href="/FinSight/developers/api">API &amp; RPC</a>.</p>',14)])])}const g=o(c,[["render",s]]);export{u as __pageData,g as default};
